param([string]$Version, [switch]$Uninstall)
$ErrorActionPreference = 'Stop'
$Repo = if ($env:DIXY_REPO) { $env:DIXY_REPO } else { 'roy-gunjan743/DIXY-CLI' }
$InstallDir = if ($env:DIXY_HOME) { $env:DIXY_HOME } else { Join-Path $env:USERPROFILE '.dixy' }
$BinDir = Join-Path $InstallDir 'bin'
if ($Uninstall) { Remove-Item $InstallDir -Recurse -Force -ErrorAction SilentlyContinue; $path=[Environment]::GetEnvironmentVariable('Path','User'); [Environment]::SetEnvironmentVariable('Path', (($path -split ';' | Where-Object {$_ -and $_ -ne $BinDir}) -join ';'), 'User'); Write-Host "DIXY removed from $InstallDir"; exit 0 }
$java=if($env:JAVA_HOME){Join-Path $env:JAVA_HOME 'bin\java.exe'}else{'java.exe'}
try{$versionText=& $java -version 2>&1|Out-String}catch{throw 'DIXY requires Java 21 or newer. Install Temurin 21 from https://adoptium.net/ and retry.'}
if($versionText -notmatch 'version "(\d+)'){throw 'DIXY requires Java 21 or newer. Install Temurin 21 from https://adoptium.net/ and retry.'}; if([int]$Matches[1] -lt 21){throw 'DIXY requires Java 21 or newer. Install Temurin 21 from https://adoptium.net/ and retry.'}
if(-not $Version){$Version=(Invoke-RestMethod "https://api.github.com/repos/$Repo/releases/latest").tag_name.TrimStart('v')}; $url="https://github.com/$Repo/releases/download/v$Version"; $tmp=Join-Path ([IO.Path]::GetTempPath()) ([Guid]::NewGuid().ToString()); New-Item $tmp -ItemType Directory|Out-Null
try{foreach($asset in 'dixy-cli.jar','dixy-agent.jar','dixy.bat','VERSION','SHA256SUMS'){Invoke-WebRequest "$url/$asset" -OutFile (Join-Path $tmp $asset)}; $checks=Get-Content (Join-Path $tmp 'SHA256SUMS'); foreach($asset in 'dixy-cli.jar','dixy-agent.jar'){$expected=($checks|Where-Object{$_ -match "  $asset$"}).Split(' ')[0];$actual=(Get-FileHash (Join-Path $tmp $asset) -Algorithm SHA256).Hash.ToLowerInvariant();if($expected -ne $actual){throw "Checksum verification failed for $asset"}}; New-Item $InstallDir -ItemType Directory -Force|Out-Null;New-Item $BinDir -ItemType Directory -Force|Out-Null;Copy-Item (Join-Path $tmp 'dixy-cli.jar'),(Join-Path $tmp 'dixy-agent.jar'),(Join-Path $tmp 'VERSION') $InstallDir -Force;Copy-Item (Join-Path $tmp 'dixy.bat') (Join-Path $InstallDir 'dixy.bat') -Force;Set-Content (Join-Path $BinDir 'dixy.bat') '@call "%~dp0..\dixy.bat" %*';$path=[Environment]::GetEnvironmentVariable('Path','User');if(($path-split ';')-notcontains $BinDir){[Environment]::SetEnvironmentVariable('Path',(($path.TrimEnd(';')+';'+$BinDir).Trim(';')),'User')};Write-Host "DIXY $Version installed in $InstallDir. Open a new terminal to use dixy."}finally{Remove-Item $tmp -Recurse -Force -ErrorAction SilentlyContinue}
